    if(ui.role==='seller'){const {data:shop}=await db.from('seller_shops').select('id').eq('owner_id',ui.user.id).maybeSingle();if(shop){const {data}=await db.from('seller_products_profile_public').select('id,name,price,image_urls,shop_id').eq('shop_id',shop.id).order('created_at',{ascending:false});(data||[]).forEach(item=>items.unshift({id:item.id,name:item.name,price:item.price,image:item.image_urls?.[0]||'',shop:item.shop_id}));}}
    const modal=document.createElement('div');modal.className='alee-chat-options-overlay';modal.innerHTML=`<section class="alee-chat-catalog-picker" role="dialog" aria-modal="true" aria-label="Choose a product"><header><h2>Catalog</h2><input type="search" placeholder="Search products" aria-label="Search catalog"></header><div class="alee-chat-catalog-list">${items.map((item,index)=>`<button type="button" data-catalog-item="${index}"><img src="${esc(item.image||'assets/alee-logo.png')}" alt="" loading="lazy"><span><strong>${esc(item.name)}</strong><small>LKR ${Number(item.price||0).toLocaleString()}</small></span><i>＋</i></button>`).join('')||'<p class="alee-chat-status">No catalog items are available.</p>'}</div><button type="button" class="alee-chat-options-close">Close</button></section>`;overlay.appendChild(modal);
    const render=()=>{const q=modal.querySelector('input').value.trim().toLowerCase();modal.querySelectorAll('[data-catalog-item]').forEach(button=>button.hidden=!items[Number(button.dataset.catalogItem)].name.toLowerCase().includes(q));};modal.querySelector('input').addEventListener('input',render);
    modal.addEventListener('click',async event=>{if(event.target===modal||event.target.closest('.alee-chat-options-close')){modal.remove();return;}const button=event.target.closest('[data-catalog-item]');if(!button)return;const item=items[Number(button.dataset.catalogItem)],image=item.image?new URL(item.image,location.href).href:'';const url=new URL('index.html',location.href);url.searchParams.set('product',String(item.id));modal.remove();await sendStructuredAction({type:'product',title:'Catalog item',name:item.name,price:Number(item.price||0),image,url:url.href});});
