  async function loadQuickReplies(){
    try{const key=`alee-chat-quick-replies:${ui.user.id}`,saved=JSON.parse(localStorage.getItem(key)||'[]');ui.quickReplies=Array.isArray(saved)?saved.filter(row=>row&&typeof row.shortcut==='string'&&typeof row.message==='string'):[];}catch(_){ui.quickReplies=[];}return ui.quickReplies;
  }
  function saveQuickReplies(){try{localStorage.setItem(`alee-chat-quick-replies:${ui.user.id}`,JSON.stringify(ui.quickReplies));return true;}catch(_){const status=mainEl.querySelector('#aleeChatStatus');if(status)status.textContent='Could not save Quick Replies in this browser.';return false;}}
  async function openQuickReplies(editMode=false){
    const replies=await loadQuickReplies();const modal=document.createElement('div');modal.className='alee-chat-options-overlay';modal.innerHTML=`<section class="alee-chat-quick-replies" role="dialog" aria-modal="true" aria-label="Quick Replies"><header><h2>Quick Replies</h2><button type="button" data-edit-replies>${editMode?'Done':'Edit'}</button></header><div class="alee-quick-reply-form-wrap" hidden><form class="alee-quick-reply-form"><label>Shortcut<input name="shortcut" maxlength="40" placeholder="e.g. thanks" required></label><label>Reply<textarea name="message" maxlength="1500" rows="4" placeholder="Write your saved reply" required></textarea></label><input name="original" type="hidden"><button type="submit">Save reply</button><button type="button" data-cancel-edit>Cancel</button></form></div><button type="button" class="alee-quick-reply-add" data-add-reply>＋ Add quick reply</button><div class="alee-quick-reply-list">${replies.map((item,i)=>`<article class="alee-quick-reply-item"><div><strong>${esc(item.shortcut)}</strong><p>${esc(item.message)}</p></div><button type="button" data-use-reply="${i}" aria-label="Use reply">↩</button>${editMode?`<button type="button" data-edit-reply="${i}">Edit</button><button type="button" data-delete-reply="${i}" aria-label="Delete reply">×</button>`:''}</article>`).join('')||'<p class="alee-quick-reply-empty">No saved replies yet. Add one to keep it here for next time.</p>'}</div><button type="button" class="alee-chat-options-close">Close</button></section>`;overlay.appendChild(modal);
    const form=modal.querySelector('.alee-quick-reply-form'),formWrap=modal.querySelector('.alee-quick-reply-form-wrap');
    modal.addEventListener('click',event=>{if(event.target===modal||event.target.closest('.alee-chat-options-close')){modal.remove();return;}if(event.target.closest('[data-edit-replies]')){const next=!editMode;modal.remove();openQuickReplies(next);return;}if(event.target.closest('[data-add-reply]')){form.reset();form.elements.original.value='';formWrap.hidden=false;form.elements.shortcut.focus();return;}if(event.target.closest('[data-cancel-edit]')){form.reset();formWrap.hidden=true;return;}const use=event.target.closest('[data-use-reply]');if(use){const item=ui.quickReplies[Number(use.dataset.useReply)],area=mainEl.querySelector('#aleeChatSend [name="body"]');if(item&&area){area.value=item.message;area.focus();area.dispatchEvent(new Event('input',{bubbles:true}));}modal.remove();return;}const edit=event.target.closest('[data-edit-reply]');if(edit){const item=ui.quickReplies[Number(edit.dataset.editReply)];form.elements.shortcut.value=item.shortcut;form.elements.message.value=item.message;form.elements.original.value=item.shortcut;formWrap.hidden=false;form.elements.shortcut.focus();return;}const remove=event.target.closest('[data-delete-reply]');if(remove){ui.quickReplies.splice(Number(remove.dataset.deleteReply),1);saveQuickReplies();modal.remove();openQuickReplies(true);}});
    form.addEventListener('submit',event=>{event.preventDefault();const shortcut=form.elements.shortcut.value.trim().replace(/^\/+/,''),message=form.elements.message.value.trim(),original=form.elements.original.value;if(!shortcut||!message)return;const oldIndex=original?ui.quickReplies.findIndex(item=>item.shortcut===original):-1;const duplicate=ui.quickReplies.findIndex(item=>item.shortcut.toLowerCase()===shortcut.toLowerCase());if(duplicate>=0&&duplicate!==oldIndex){alert('A reply with this shortcut already exists.');return;}if(oldIndex>=0)ui.quickReplies.splice(oldIndex,1);ui.quickReplies.unshift({shortcut,message});if(!saveQuickReplies())return;modal.remove();openQuickReplies(true);});
  }
  function openActionForm(type){
    const config={product:{title:'Send Product',fields:[['name','Product name','text'],['price','Price','number'],['url','Product link','url'],['image','Photo link (optional)','url']]},offer:{title:'Send Offer',fields:[['price','Offer price','number'],['note','Offer details','text']]},payment:{title:'Request Payment',fields:[['amount','Amount','number'],['note','Payment details','text']]},status:{title:'Share Order Status',fields:[['order','Order number (optional)','text'],['note','Status update','text'],['tracking','Tracking link (optional)','url']]},shipped:{title:'Order Shipped',fields:[['order','Order number','text'],['tracking','Tracking link (optional)','url'],['note','Courier or delivery note','text']]},invoice:{title:'Send Invoice',fields:[['order','Order number','text'],['items','Items','text'],['amount','Total amount','number'],['note','Payment note','text']]},tracking:{title:'Share Tracking',fields:[['order','Order number','text'],['tracking','Tracking link','url'],['note','Courier name (optional)','text']]},catalog:{title:'Send Catalog Item',fields:[['name','Product name','text'],['price','Price','number'],['url','Product link (optional)','url'],['image','Photo link (optional)','url']]},contact:{title:'Share Contact',fields:[['name','Name','text'],['phone','Phone number','tel'],['note','Details (optional)','text']]},poll:{title:'Create a Poll',fields:[['question','Question','text'],['option1','Option 1','text'],['option2','Option 2','text'],['option3','Option 3 (optional)','text']]},event:{title:'Share an Event',fields:[['name','Event name','text'],['date','Date and time','datetime-local'],['location','Location (optional)','text'],['note','Details (optional)','text']]}}[type];
    if(!config)return;const modal=document.createElement('div');modal.className='alee-chat-options-overlay';
    modal.innerHTML=`<form class="alee-chat-action-form"><h2>${esc(config.title)}</h2>${config.fields.map(([name,label,inputType])=>`<label>${esc(label)}<input name="${name}" type="${inputType}" ${inputType==='number'?'min="0" step="0.01"':''} ${name==='name'||name==='amount'||name==='price'||name==='note'||type==='shipped'&&name==='order'||type==='invoice'&&name==='order'||type==='tracking'&&name==='tracking'?'required':''}></label>`).join('')}<div class="alee-chat-action-form-buttons"><button type="button" data-action-cancel>Cancel</button><button type="submit">Send in chat</button></div></form>`;
    overlay.appendChild(modal);modal.addEventListener('click',event=>{if(event.target===modal||event.target.closest('[data-action-cancel]'))modal.remove();});
    modal.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget));if(type==='poll'&&(!values.question||!values.option1||!values.option2)){alert('Add a question and at least two options.');return;}if(type==='event'&&!values.date){alert('Choose the event date and time.');return;}const action={type:type==='catalog'?'product':type,title:config.title,...values};if(type==='shipped')action.status='Shipped';if(type==='contact')action.note=`${values.name} · Phone: ${values.phone}${values.note?` · ${values.note}`:''}`;if(type==='poll')action.note=`${values.question} · ${[values.option1,values.option2,values.option3].filter(Boolean).join(' / ')}`;if(type==='event')action.note=`${values.date}${values.location?` · ${values.location}`:''}${values.note?` · ${values.note}`:''}`;await sendStructuredAction(action);modal.remove();});modal.querySelector('input')?.focus();
  }
  async function sendCurrentLocation(){const status=mainEl.querySelector('#aleeChatStatus');if(!navigator.geolocation){if(status)status.textContent='Location is not available in this browser.';return;}if(status)status.textContent='Getting your location…';navigator.geolocation.getCurrentPosition(async position=>{const lat=position.coords.latitude,lon=position.coords.longitude;await sendStructuredAction({type:'location',title:'Shared location',lat,lon,url:`https://maps.google.com/?q=${lat},${lon}`});if(status)status.textContent='';},error=>{if(status)status.textContent=error.code===1?'Allow location access to share your location.':'Could not get your location.';},{enableHighAccuracy:false,timeout:10000,maximumAge:60000});}
  async function sendStructuredAction(action){const body='::ALEE_CHAT_ACTION::'+JSON.stringify(action);if(body.length>3900){const status=mainEl.querySelector('#aleeChatStatus');if(status)status.textContent='That message is too long.';return;}const message={conversation_id:ui.conversationId,sender_id:ui.user.id,body};const expiry=Number(ui.preferences[ui.conversationId]?.disappearing_seconds||0);if(expiry)message.expires_at=new Date(Date.now()+expiry*1000).toISOString();if(ui.isGroup)message.sender_label=ui.user.user_metadata?.full_name||ui.user.user_metadata?.name||ui.user.email||'Member';const {error}=await db.from('seller_messages').insert(message);const status=mainEl.querySelector('#aleeChatStatus');if(error){if(status)status.textContent=`Could not send chat details: ${error.message}`;return;}if(status)status.textContent='';await loadMessages();}
  async function blockCurrentPeer(){if(!ui.peerId)return;const {error}=await db.from('seller_chat_blocks').insert({user_id:ui.user.id,blocked_user_id:ui.peerId});const status=mainEl.querySelector('#aleeChatStatus');if(error){if(status)status.textContent=`Could not block user. Run the latest seller-chat-schema.sql. ${error.message}`;return;}ui.blockedIds.add(ui.peerId);ui.isBlocked=true;const form=mainEl.querySelector('#aleeChatSend');if(form)form.hidden=true;if(status)status.textContent='This user is blocked. You will not be able to send messages.';}
  function safeLink(value){try{const url=new URL(String(value||''));return ['http:','https:'].includes(url.protocol)?url.href:'';}catch(_){return '';}}
  function renderOrderMessage(body){const lines=String(body||'').split('\n'),title=esc(lines[0]||'New order'),fields=lines.slice(1).map(line=>{const split=line.indexOf(':');if(split<0)return '';const key=line.slice(0,split).trim(),value=line.slice(split+1).trim();if(!value)return '';return `<div><small>${esc(key)}</small><strong>${esc(value)}</strong></div>`;}).filter(Boolean);return `<section class="alee-chat-action-card order"><b>${title}</b>${fields.join('')}</section>`;}
  function renderActionBody(body){
    try{
      const action=JSON.parse(body.slice('::ALEE_CHAT_ACTION::'.length)),title=esc(action.title||'Chat update'),line=(label,value)=>value?`<div><small>${label}</small><strong>${esc(value)}</strong></div>`:'',link=safeLink(action.url||action.tracking),image=safeLink(action.image);
      if(action.type==='product')return `<section class="alee-chat-action-card product">${image?`<img src="${esc(image)}" alt="${esc(action.name)}">`:''}<div><b>${title}</b><strong>${esc(action.name||'Product')}</strong>${line('Price',action.price?`LKR ${action.price}`:'')}${link?`<a href="${esc(link)}" target="_blank" rel="noopener">View product</a>`:''}</div></section>`;
      if(action.type==='offer')return `<section class="alee-chat-action-card offer"><b>${title}</b>${line('Offer price',action.price?`LKR ${action.price}`:'')}${line('Details',action.note)}</section>`;
      if(action.type==='payment')return `<section class="alee-chat-action-card payment"><b>${title}</b>${line('Amount',action.amount?`LKR ${action.amount}`:'')}${line('Details',action.note)}</section>`;
      if(action.type==='contact')return `<section class="alee-chat-action-card"><b>${title}</b>${line('Name',action.name)}${line('Phone',action.phone)}${line('Details',action.note)}</section>`;
      if(action.type==='poll')return `<section class="alee-chat-action-card"><b>${title}</b>${line('Question',action.question)}${line('Option 1',action.option1)}${line('Option 2',action.option2)}${line('Option 3',action.option3)}</section>`;
      if(action.type==='event')return `<section class="alee-chat-action-card"><b>${title}</b>${line('Date and time',action.date)}${line('Location',action.location)}${line('Details',action.note)}</section>`;
      if(action.type==='location')return `<section class="alee-chat-action-card"><b>${title}</b>${line('Coordinates',`${action.lat}, ${action.lon}`)}${link?`<a href="${esc(link)}" target="_blank" rel="noopener">Open map</a>`:''}</section>`;
      if(action.type==='invoice')return `<section class="alee-chat-action-card invoice"><b>${title}</b>${line('Order',action.order)}${line('Items',action.items)}${line('Total',action.amount?`LKR ${action.amount}`:'')}${line('Note',action.note)}</section>`;
      return `<section class="alee-chat-action-card order"><b>${title}</b>${line('Order',action.order)}${line('Status',action.status||action.note)}${link?`<a href="${esc(link)}" target="_blank" rel="noopener">Open tracking</a>`:''}</section>`;
    }catch(_){return `<div>${esc(body)}</div>`;}
  }
  async function toggleFavorite(id,items){const current=ui.preferences[id]||{};const next=!current.is_favorite;const {error}=await db.from('seller_chat_preferences').upsert({user_id:ui.user.id,conversation_id:id,is_favorite:next},{onConflict:'user_id,conversation_id'});if(error){showError('Could not save favourite. Run the latest seller-chat-schema.sql.');return;}ui.preferences[id]={...current,is_favorite:next};renderConversationList(items.map(x=>x.row),ui.role);}
  async function setRead(id){const {error}=await db.from('seller_chat_preferences').upsert({user_id:ui.user.id,conversation_id:id,last_read_at:new Date().toISOString()},{onConflict:'user_id,conversation_id'});if(error)console.warn('Could not update chat read state',error.message);}
  function callStatus(text){const el=mainEl.querySelector('#aleeCallStatus');if(el)el.textContent=text;}
  function showCallPanel(text,actions=[]){const panel=mainEl.querySelector('#aleeCallPanel'),root=mainEl.querySelector('#aleeCallActions');if(!panel||!root)return;panel.hidden=false;panel.classList.toggle('video-call',ui.callMode==='video');panel.classList.toggle('voice-call',ui.callMode!=='video');let brand=panel.querySelector('.alee-call-brand');if(!brand){brand=document.createElement('header');brand.className='alee-call-brand';brand.innerHTML='<span class="alee-call-brand-spacer"></span><div><strong></strong><small>🔒 End-to-end encrypted</small></div><button type="button" data-call-close aria-label="Close call screen">×</button>';panel.prepend(brand);}brand.querySelector('strong').textContent=ui.callPeerLabel||titleEl.textContent||'ALEE SHOPPING';let center=panel.querySelector('.alee-call-center');if(!center){center=document.createElement('div');center.className='alee-call-center';center.innerHTML='<img alt="Contact profile"><strong></strong>';panel.insertBefore(center,panel.querySelector('#aleeCallRemote'));}center.querySelector('img').src=ui.callPeerLogo||'assets/alee-logo.png';center.querySelector('strong').textContent=ui.callPeerLabel||titleEl.textContent||'ALEE SHOPPING';callStatus(text);const incoming=Boolean(ui.pendingOffer),mode=ui.callMode||'voice';const controls=incoming?[{id:'accept',label:'Answer',icon:'fa-phone',kind:'answer'},{id:'decline',label:'Decline',icon:'fa-phone-slash',kind:'end'}]:[{id:'speaker',label:'Audio',icon:'fa-volume-high'},{id:'video',label:'Video',icon:'fa-video',disabled:mode!=='video'&&!ui.callLocalStream},{id:'mute',label:'Mute',icon:'fa-microphone'},{id:'more',label:'More',icon:'fa-ellipsis'},{id:'share',label:'Share',icon:'fa-arrow-up-from-bracket'},{id:'hangup',label:'End',icon:'fa-phone-slash',kind:'end'}];root.innerHTML=controls.map(({id,label,icon,kind,disabled})=>`<button type="button" class="${kind||''}" data-call-action="${id}" ${disabled?'disabled':''}><i class="fa-solid ${icon}"></i><span>${label}</span></button>`).join('');root.querySelectorAll('[data-call-action]').forEach(button=>button.addEventListener('click',async()=>{const action=button.dataset.callAction;if(action==='accept')await acceptCall();else if(action==='decline')await declineCall();else if(action==='hangup')await hangupCall();else if(action==='mute'){const tracks=ui.callLocalStream?.getAudioTracks()||[];const next=tracks.some(track=>track.enabled);tracks.forEach(track=>track.enabled=!next);button.classList.toggle('active',!next);button.querySelector('span').textContent=next?'Unmute':'Mute';}else if(action==='video'){const tracks=ui.callLocalStream?.getVideoTracks()||[];const next=tracks.some(track=>track.enabled);tracks.forEach(track=>track.enabled=!next);button.classList.toggle('active',!next);}else if(action==='speaker'){const audio=mainEl.querySelector('#aleeCallRemoteAudio');if(audio)audio.muted=!audio.muted;button.classList.toggle('active',!audio?.muted);}else if(action==='share'&&navigator.share){navigator.share({title:ui.callPeerLabel||'Call',text:'ALEE SHOPPING call'}).catch(()=>{});}else if(action==='more'){let menu=panel.querySelector('.alee-call-more-menu');if(!menu){menu=document.createElement('div');menu.className='alee-call-more-menu';menu.innerHTML='<button type="button" data-call-close>End call and return to chat</button>';panel.appendChild(menu);menu.querySelector('[data-call-close]').addEventListener('click',()=>hangupCall());}else menu.remove();}}));panel.querySelectorAll('[data-call-close]').forEach(button=>button.addEventListener('click',()=>{hangupCall();}));}
  async function sendCallSignal(kind,payload={}){if(!ui.callId||!ui.callPeerId)return {error:new Error('Call is not ready.')};return db.from('seller_call_signals').insert({conversation_id:ui.conversationId,call_id:ui.callId,sender_id:ui.user.id,recipient_id:ui.callPeerId,kind,payload});}
  async function startMedia(mode){if(!navigator.mediaDevices?.getUserMedia)throw new Error('Calls need a secure HTTPS website and a browser that supports camera and microphone.');const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:mode==='video'});ui.callLocalStream=stream;const local=mainEl.querySelector('#aleeCallLocal');if(local){local.srcObject=stream;local.hidden=mode!=='video';}const remote=mainEl.querySelector('#aleeCallRemote'),audio=mainEl.querySelector('#aleeCallRemoteAudio');if(remote){remote.hidden=mode!=='video';remote.srcObject=null;}if(audio)audio.srcObject=null;return stream;}
  function makePeerConnection(){const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun1.l.google.com:19302'}]});ui.callConnection=pc;ui.callRemoteStream=new MediaStream();pc.ontrack=event=>{const stream=event.streams?.[0];if(stream)ui.callRemoteStream=stream;else ui.callRemoteStream.addTrack(event.track);const remote=mainEl.querySelector('#aleeCallRemote'),audio=mainEl.querySelector('#aleeCallRemoteAudio');if(ui.callMode==='video'&&remote){remote.srcObject=ui.callRemoteStream;remote.play().catch(()=>{});}else if(audio){audio.srcObject=ui.callRemoteStream;audio.play().catch(()=>{});}};pc.onicecandidate=event=>{if(event.candidate){if(!ui.callDescriptionSent)(ui.queuedLocalIce||(ui.queuedLocalIce=[])).push(event.candidate.toJSON());else sendCallSignal('ice',{candidate:event.candidate.toJSON()});}};pc.onconnectionstatechange=()=>{if(['failed','disconnected'].includes(pc.connectionState))callStatus('Connection interrupted. Check both devices’ internet connections.');};ui.callLocalStream?.getTracks().forEach(track=>pc.addTrack(track,ui.callLocalStream));return pc;}
