  async function onCallSignal(signal){if(!signal||signal.recipient_id!==ui.user?.id)return;if(signal.kind==='offer'){if(ui.callId){await db.from('seller_call_signals').insert({conversation_id:ui.conversationId,call_id:signal.call_id,sender_id:ui.user.id,recipient_id:signal.sender_id,kind:'reject',payload:{reason:'busy'}});return;}ui.callId=signal.call_id;ui.callPeerId=signal.sender_id;ui.callMode=signal.payload?.mode==='video'?'video':'voice';ui.pendingOffer=signal.payload;ui.queuedIce=[];showCallPanel(`Incoming ${ui.callMode} call`,[{id:'accept',label:'Answer',icon:'fa-phone',kind:'answer'},{id:'decline',label:'Decline',icon:'fa-phone-slash',kind:'end'}]);return;}if(signal.call_id!==ui.callId||signal.sender_id!==ui.callPeerId)return;if(signal.kind==='answer'){try{await ui.callConnection?.setRemoteDescription(signal.payload.sdp);for(const candidate of ui.queuedIce.splice(0))await ui.callConnection?.addIceCandidate(candidate);callStatus(ui.callMode==='video'?'Video call connected':'Voice call connected');}catch(error){callStatus(`Could not connect call: ${error.message}`);await cleanupCall();}}else if(signal.kind==='ice'&&signal.payload?.candidate){if(ui.callConnection?.remoteDescription)await ui.callConnection.addIceCandidate(signal.payload.candidate).catch(()=>{});else ui.queuedIce.push(signal.payload.candidate);}else if(signal.kind==='end'||signal.kind==='reject'){const msg=signal.kind==='reject'?'Call declined':'Call ended';await cleanupCall();const status=mainEl.querySelector('#aleeChatStatus');if(status)status.textContent=msg;}}
