    let savedWallpaper='shop-white';try{savedWallpaper=normalizeWallpaper(localStorage.getItem(chatWallpaperKey())||'shop-white');applyChatBubbleColor(localStorage.getItem(`alee-chat-theme:${ui.user.id}:${ui.conversationId}`)||'default');}catch(_){}applyChatWallpaper(savedWallpaper);
