    const {data:callConversation}=await db.from('seller_conversations').select('buyer_id,seller_id,shop_id').eq('id',id).maybeSingle();ui.peerId=isGroup?null:callConversation?(callConversation.buyer_id===ui.user.id?callConversation.seller_id:callConversation.buyer_id):null;ui.isBlocked=ui.peerId?ui.blockedIds.has(ui.peerId):false;ui.callPeerLabel=label||'ALEE SHOPPING';ui.callPeerLogo='assets/alee-logo.png';if(callConversation?.shop_id){const {data:shopLogo}=await db.from('seller_shops_public').select('logo_url').eq('id',callConversation.shop_id).maybeSingle();if(shopLogo?.logo_url)ui.callPeerLogo=shopLogo.logo_url;}
